import com.wolinski.shop.platform.ShopProblem;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** A discount rate as whole basis points (12.5% is 1250), per docs/adr/0008. */
final class DiscountPercent {

    private static final Pattern TEXT = Pattern.compile("(\\d{1,3})(?:\\.(\\d{1,2}))?");
    private static final long HUNDRED_PERCENT = 10_000;

    private DiscountPercent() {
    }

    /** Parses admin-form text such as "12.5" into basis points. */
    static long parseBasisPoints(String percent) {
        if (null == percent) {
            throw new ShopProblem("DISCOUNT_NOT_A_PERCENT", "Discount is missing");
        }
        Matcher m = TEXT.matcher(percent.trim());
        if (false == m.matches()) {
            throw new ShopProblem("DISCOUNT_NOT_A_PERCENT", "Discount is not a percentage: " + percent);
        }
        long whole = Long.parseLong(m.group(1));
        long fraction = 0;
        if (null != m.group(2)) {
            String digits = m.group(2);
            fraction = Long.parseLong(digits) * (digits.length() == 1 ? 10 : 1);
        }
        long basisPoints = whole * 100 + fraction;
        if (basisPoints <= 0 || basisPoints > HUNDRED_PERCENT) {
            throw new ShopProblem("DISCOUNT_OUT_OF_RANGE", "Discount must be above 0 and at most 100: " + percent);
        }
        return basisPoints;
    }

    /** The discount on {@code minorUnits} at {@code basisPoints}, rounded half up to a whole minor unit. */
    static long discountOf(long minorUnits, long basisPoints) {
        return (minorUnits * basisPoints + HUNDRED_PERCENT / 2) / HUNDRED_PERCENT;
    }
}
}

