import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.platform.ShopProblem;
import org.junit.jupiter.api.Test;

class DiscountPercentTest {

    @Test
    void parsesTextIntoBasisPoints() {
        assertEquals(1250, DiscountPercent.parseBasisPoints("12.5"));
        assertEquals(1200, DiscountPercent.parseBasisPoints("12"));
        assertEquals(1205, DiscountPercent.parseBasisPoints("12.05"));
        assertEquals(50, DiscountPercent.parseBasisPoints(" 0.5 "));
        assertEquals(10_000, DiscountPercent.parseBasisPoints("100"));
    }

    @Test
    void rejectsTextThatIsNotAPercentage() {
        for (String text : new String[] {"", "abc", "1,5", "-5", "1e2", "12.345", "12.", ".5", "1234"}) {
            ShopProblem problem = assertThrows(ShopProblem.class, () -> DiscountPercent.parseBasisPoints(text));
            assertEquals("DISCOUNT_NOT_A_PERCENT", problem.code());
        }
        assertEquals("DISCOUNT_NOT_A_PERCENT",
                assertThrows(ShopProblem.class, () -> DiscountPercent.parseBasisPoints(null)).code());
    }

    @Test
    void rejectsRatesOutsideZeroToOneHundred() {
        for (String text : new String[] {"0", "0.00", "100.01", "999"}) {
            ShopProblem problem = assertThrows(ShopProblem.class, () -> DiscountPercent.parseBasisPoints(text));
            assertEquals("DISCOUNT_OUT_OF_RANGE", problem.code());
        }
    }

    @Test
    void discountRoundsHalfUpToAWholeMinorUnit() {
        assertEquals(1, DiscountPercent.discountOf(100, 50));   // 0.5% of 1.00 PLN = 0.01 PLN
        assertEquals(0, DiscountPercent.discountOf(99, 50));    // 0.495 -> 0
        assertEquals(2, DiscountPercent.discountOf(333, 6_000)); // 19.98 -> 20 wait: 333*60%=199.8 -> 200
        assertEquals(200, DiscountPercent.discountOf(333, 6_000));
        assertEquals(0, DiscountPercent.discountOf(0, 1_250));
        assertEquals(10_000, DiscountPercent.discountOf(10_000, 10_000));
    }
}
}

